MOD = 10**9 + 7
cnt = {}
for x in input().split():
    v = int(x)
    cnt[v] = cnt.get(v, 0) + 1

ans = 0
cur = 1
for i in range(1, n + 1):
    if i not in cnt:
        break
    cur = (cur * cnt[i]) % MOD
    ans = (ans + cur) % MOD

print(ans)
```

